refentry.refsect1:
  &reftitle.examples;

   Ejemplo de untaint


<?php
$id = "42";
taint($id);
if (preg_match('/^\d+$/', $id)) {
    // validado estrictamente como dígitos: es seguro confiar en él
    untaint($id);
}
var_dump(is_tainted($id));
?>


   &example.outputs.similar;


bool(false)

&reftitle.notes;


  Solo los valores de tipo cadena pueden llevar la marca; pasar un valor que
  no sea una cadena no tiene ningún efecto.
